const payload = $json.body ?? $json;
const event = payload.bot_event ?? payload.event;
const failures = new Set(['bot.denied', 'bot.notallowed', 'bot.failed', 'bot.recording_permission_denied']);
if (!failures.has(event)) return [];
if (!payload.bot_id) throw new Error('MeetStream webhook did not include bot_id.');
return [{ json: { ...payload, bot_event: event, bot_id: String(payload.bot_id) } }];

const event = $('Keep actionable failures').item.json;
const bot = $json.bot_details ?? $json;
const reason = event.message ?? bot.message ?? 'MeetStream did not provide a failure message.';
const meetingLink = bot.MeetingLink ?? bot.meeting_link ?? bot.meeting_url ?? event.meeting_link ?? 'Not provided';
return [{ json: {
  bot_id: event.bot_id,
  bot_event: event.bot_event,
  reason,
  meeting_link: meetingLink,
  occurred_at: event.timestamp ?? new Date().toISOString(),
  body: `MeetStream needs attention.\n\nEvent: ${event.bot_event}\nReason: ${reason}\nBot ID: ${event.bot_id}\nMeeting: ${meetingLink}\nTime: ${event.timestamp ?? 'Not provided'}\n\nOpen MeetStream and the meeting host controls before retrying.`
} }];
